    void check(boolean ok,String message){if(!ok)throw new AssertionError(message);checks++;}
    Object call(MainActivity a,String method,Class<?>[] types,Object... args)throws Exception{Method m=MainActivity.class.getDeclaredMethod(method,types);m.setAccessible(true);return m.invoke(a,args);}
