    byte[] png(int color)throws Exception{Bitmap b=Bitmap.createBitmap(240,320,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(b);Paint p=new Paint();p.setColor(color);c.drawRoundRect(40,35,200,290,12,12,p);ByteArrayOutputStream out=new ByteArrayOutputStream();b.compress(Bitmap.CompressFormat.PNG,100,out);b.recycle();return out.toByteArray();}
