        MainActivity a=(MainActivity)runner.startActivitySync(new Intent(root,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Field field=MainActivity.class.getDeclaredField("db");field.setAccessible(true);MainActivity.DB db=(MainActivity.DB)field.get(a);JSONArray families=boot(a).getJSONObject("settings").getJSONArray("families");check(families.length()==2,"Existing child names must become profiles");String elder=families.getJSONObject(0).getString("id"),younger=families.getJSONObject(1).getString("id");
