        top=data(a,"save",new JSONObject().put("id",tid).put("relatedIds",new JSONArray().put(bid).put(tid).put(bid)));check(top.getJSONArray("relatedIds").length()==1&&db.get(bid).getJSONArray("relatedIds").getString(0).equals(tid),"Link must be reciprocal and deduplicate/self filter");data(a,"save",new JSONObject().put("id",bid).put("relatedIds",new JSONArray()));check(db.get(tid).getJSONArray("relatedIds").length()==0,"Removing a link from either side must unlink both");top=data(a,"save",new JSONObject().put("id",tid).put("relatedIds",new JSONArray().put(bid)));
