        JSONObject person=attach(a,input,elder,"avatar");String originalAvatar=person.getString("avatarId");person=data(a,"saveAvatarCrop",new JSONObject().put("id",elder).put("png",dataURL(png(Color.rgb(180,145,105)))));check(!person.getString("avatarId").equals(originalAvatar)&&new File(a.getFilesDir(),"media/"+person.getString("avatarId")+".jpg").isFile(),"Cropped avatar receives an immutable photo ID");person=data(a,"saveFamily",new JSONObject().put("id",elder).put("name","お姉ちゃん"));check(db.get(tid).getJSONArray("ownerIds").getString(0).equals(elder)&&db.get(tid).getJSONArray("children").getString(0).equals("お姉ちゃん"),"Rename must preserve owner IDs and update display names");check(boot(a).getJSONObject("settings").getJSONArray("families").length()==2,"Rename must not recreate old default profile");
        ByteArrayOutputStream backup=new ByteArrayOutputStream();AlbumBackup.write(a,db,backup);Map<String,byte[]> entries=unzip(backup.toByteArray());JSONObject manifest=new JSONObject(new String(entries.get("manifest.json"),StandardCharsets.UTF_8));check(manifest.getInt("version")==2&&manifest.getJSONArray("families").length()==2,"Backup v2 must include family records");check(entries.containsKey("media/"+backId+".png")&&entries.containsKey("media/"+memoryId+".jpg")&&entries.containsKey("media/"+person.getString("avatarId")+".jpg"),"Backup must include back, memory and avatar pixels");String html=new String(entries.get("closet.html"),StandardCharsets.UTF_8);check(html.contains(backId)&&html.contains(memoryId)&&html.contains(person.getString("avatarId"))&&html.contains("\\u003c思い出\\u003e"),"HTML must embed and safely escape extended album");File exported=new File(root.getCacheDir(),"family-portable-check.html");SyncStore.atomic(exported,entries.get("closet.html"));
